const { GlueClient, StartCrawlerCommand } = require('@aws-sdk/client-glue');
const { S3Client, PutObjectCommand } = require('@aws-sdk/client-s3');
const { DynamoDBClient, PutItemCommand } = require('@aws-sdk/client-dynamodb');

exports.handler = async (event) => {
  const s3Record = event.Records[0].s3;
  const bucket = s3Record.bucket.name;
  const key = decodeURIComponent(s3Record.object.key.replace(/\+/g, ' '));

  const glue = new GlueClient({});
  await glue.send(new StartCrawlerCommand({ Name: 'csv-crawler' }));

  // ETL: Normalize headers, drop rows with missing values
  const cleanedData = await processCSV(bucket, key);

  const s3 = new S3Client({});
  await s3.send(new PutObjectCommand({
    Bucket: bucket,
    Key: `cleaned/${key}`,
    Body: cleanedData,
    ServerSideEncryption: 'aws:kms'
  }));

  const dynamo = new DynamoDBClient({});
  await dynamo.send(new PutItemCommand({
    TableName: 'file-index',
    Item: {
      fileId: { S: key },
      s3Key: { S: key },
      rowCount: { N: '100' },
      columnCount: { N: '5' },
      status: { S: 'COMPLETED' }
    }
  }));
};
```

